//! Bit-exact reimplementation of .NET Framework's `System.Random`.
//!
//! Not a GTA V format, but the key loader depends on it. `GTA5Keys.UseMagicData`
//! unmasks `magic.dat` by seeding `new Random(...)` with the Jenkins hash of the
//! AES key and subtracting four generated byte streams. Any deviation in this
//! generator produces garbage keys, which produces a garbage archive index, with
//! no error along the way to say what went wrong. So it has to match exactly,
//! not approximately.
//!
//! The algorithm is Knuth's subtractive generator as shipped in .NET Framework
//! (and preserved for the seeded constructor in .NET Core for compatibility).
//! Do not substitute a "better" PRNG: fidelity is the entire point.

const MBIG: i32 = i32::MAX;
const MSEED: i32 = 161_803_398;

/// A seeded `System.Random`. Only the members the key loader uses are ported.
pub struct NetRandom {
    seed_array: [i32; 56],
    inext: usize,
    inextp: usize,
}

impl NetRandom {
    /// Port of `Random(int Seed)`.
    pub fn new(seed: i32) -> Self {
        // `Math.Abs(int.MinValue)` throws in C#, so the reference special-cases
        // it to `int.MaxValue`. That makes seeds MinValue and MaxValue produce
        // identical streams; the tests pin this.
        let subtraction = if seed == i32::MIN {
            i32::MAX
        } else {
            seed.abs()
        };

        let mut seed_array = [0i32; 56];
        let mut mj = MSEED.wrapping_sub(subtraction);
        seed_array[55] = mj;
        let mut mk: i32 = 1;

        for i in 1..55 {
            // The reference indexes with this deliberate non-sequential stride.
            let ii = (21 * i) % 55;
            seed_array[ii] = mk;
            mk = mj.wrapping_sub(mk);
            if mk < 0 {
                mk = mk.wrapping_add(MBIG);
            }
            mj = seed_array[ii];
        }

        for _ in 1..5 {
            for i in 1..56 {
                seed_array[i] = seed_array[i].wrapping_sub(seed_array[1 + (i + 30) % 55]);
                if seed_array[i] < 0 {
                    seed_array[i] = seed_array[i].wrapping_add(MBIG);
                }
            }
        }

        Self {
            seed_array,
            inext: 0,
            inextp: 21,
        }
    }

    /// Port of `Random.InternalSample()`.
    fn internal_sample(&mut self) -> i32 {
        let mut loc_inext = self.inext + 1;
        if loc_inext >= 56 {
            loc_inext = 1;
        }
        let mut loc_inextp = self.inextp + 1;
        if loc_inextp >= 56 {
            loc_inextp = 1;
        }

        let mut ret = self.seed_array[loc_inext].wrapping_sub(self.seed_array[loc_inextp]);
        if ret == MBIG {
            ret -= 1;
        }
        if ret < 0 {
            ret = ret.wrapping_add(MBIG);
        }

        self.seed_array[loc_inext] = ret;
        self.inext = loc_inext;
        self.inextp = loc_inextp;
        ret
    }

    /// Port of `Random.NextBytes(byte[])`.
    pub fn next_bytes(&mut self, buffer: &mut [u8]) {
        for slot in buffer.iter_mut() {
            *slot = (self.internal_sample() % 256) as u8;
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Expected streams captured from .NET Framework 4.8 itself, via
    /// `New-Object System.Random(seed)` in PowerShell 5.1 — the same runtime
    /// CodeWalker runs on.
    fn stream(seed: i32, len: usize) -> String {
        let mut r = NetRandom::new(seed);
        let mut buf = vec![0u8; len];
        r.next_bytes(&mut buf);
        buf.iter().map(|b| format!("{b:02X}")).collect()
    }

    #[test]
    fn matches_dotnet_for_ordinary_seeds() {
        assert_eq!(
            stream(0, 24),
            "1A0C466F5D75E4D8AD6765D5F519DBC82B7C343B37F88500"
        );
        assert_eq!(
            stream(1, 24),
            "46D086824097E4A395CFFF46699C73C4A1CD1034135B4EA3"
        );
        assert_eq!(
            stream(12345, 24),
            "DF9E02F5ADF2473C1457FD6BB75B3C017E327E589C9F3423"
        );
    }

    /// The seed is `(int)` of a `uint` hash, so negative seeds are the normal
    /// case, not an edge case.
    #[test]
    fn matches_dotnet_for_negative_seeds() {
        assert_eq!(
            stream(-902917054, 24),
            "6A0879F7F5C4F84D5EFE1138C4EE8457BFBA464D8215F8CA"
        );
        assert_eq!(
            stream(2041602005, 24),
            "DA116A498BC2BCCA88C76DD62AF19B7E518ACB42D99835B6"
        );
    }

    /// `Math.Abs` makes a seed and its negation equivalent.
    #[test]
    fn negation_yields_the_same_stream() {
        assert_eq!(stream(1, 24), stream(-1, 24));
    }

    /// `Math.Abs(int.MinValue)` would throw, so the reference substitutes
    /// `int.MaxValue`. The two seeds therefore collide.
    #[test]
    fn min_value_collides_with_max_value() {
        assert_eq!(
            stream(i32::MIN, 24),
            "1A0C4C6F5D73E4D8AD5B65D5E719DBC8177C341D37F885F8"
        );
        assert_eq!(stream(i32::MIN, 24), stream(i32::MAX, 24));
    }

    /// The unmasking pass reads streams as long as `magic.dat` (~150 KB), so
    /// the generator has to stay correct well past its 55-element warmup.
    #[test]
    fn stays_stable_over_long_streams() {
        let mut r = NetRandom::new(2041602005);
        let mut buf = vec![0u8; 150_000];
        r.next_bytes(&mut buf);
        // First 24 bytes are unchanged by the length of the request.
        let head: String = buf[..24].iter().map(|b| format!("{b:02X}")).collect();
        assert_eq!(head, "DA116A498BC2BCCA88C76DD62AF19B7E518ACB42D99835B6");
    }
}
